<?php
namespace App\Services\Events;
use App\Models\Event; use App\Models\EventRegistration; use App\Models\Member; use App\Services\Communications\DeliveryService; use App\Models\MessageTemplate; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class EventRegistrationService {
 public function __construct(private DeliveryService $delivery){}
 public function register(Member $member,Event $event):EventRegistration{$r=DB::transaction(function()use($member,$event){$event=Event::query()->lockForUpdate()->findOrFail($event->id);if($event->status!=='published')throw ValidationException::withMessages(['event'=>'Event is not open for registration.']);$now=now();if($event->registration_opens_at&&$now->lt($event->registration_opens_at))throw ValidationException::withMessages(['event'=>'Registration has not opened yet.']);if($event->registration_closes_at&&$now->gt($event->registration_closes_at))throw ValidationException::withMessages(['event'=>'Registration is closed.']);$active=$event->registrations()->whereIn('status',['registered','attended'])->count();$status=($event->capacity&&$active >= $event->capacity)?($event->waitlist_enabled?'waitlisted':null):'registered';if(!$status)throw ValidationException::withMessages(['event'=>'Event capacity has been reached.']);return EventRegistration::query()->updateOrCreate(['event_id'=>$event->id,'member_id'=>$member->id],['status'=>$status,'registered_at'=>now(),'cancelled_at'=>null]);},3);$r->load('event');$t=MessageTemplate::query()->where('code','event_registration_confirmed')->where('governance_status','published')->first();if($t)$this->delivery->deliver($member->user,$t->category,$t->subject_template,$t->body_template,['in_app','email'],['event_title'=>$r->event->title,'event_starts_at'=>$r->event->starts_at->toDayDateTimeString(),'registration_status'=>strtoupper($r->status),'action_url'=>'/events/'.$r->event_id,'dedupe_key'=>'event-registration:'.$r->id.':'.($r->registered_at?->format('Uu') ?? '0')]);return $r->fresh('event');}
 public function cancel(Member $member,EventRegistration $registration):EventRegistration{[$cancelled,$promoted]=DB::transaction(function()use($member,$registration){$registration=EventRegistration::query()->lockForUpdate()->findOrFail($registration->id);abort_unless($registration->member_id===$member->id,403);if(!in_array($registration->status,['registered','waitlisted'],true))throw ValidationException::withMessages(['status'=>'This registration cannot be cancelled.']);$event=Event::query()->lockForUpdate()->findOrFail($registration->event_id);$registration->update(['status'=>'cancelled','cancelled_at'=>now()]);$promoted=null;if($event->capacity){$active=$event->registrations()->whereIn('status',['registered','attended'])->count();if($active < $event->capacity){$promoted=$event->registrations()->where('status','waitlisted')->orderBy('registered_at')->lockForUpdate()->first();if($promoted)$promoted->update(['status'=>'registered']);}}return [$registration->fresh(),$promoted?->fresh(['member.user','event'])];},3);if($promoted){$t=MessageTemplate::query()->where('code','event_waitlist_promoted')->where('governance_status','published')->first();if($t&&$promoted->member?->user)$this->delivery->deliver($promoted->member->user,$t->category,$t->subject_template,$t->body_template,['in_app','email'],['event_title'=>$promoted->event->title,'event_starts_at'=>$promoted->event->starts_at->toDayDateTimeString(),'action_url'=>'/events/'.$promoted->event_id,'dedupe_key'=>'event-waitlist-promoted:'.$promoted->id]);}return $cancelled;}
}
